package com.hmdp.ai.runtime.tool.skill;
import com.fasterxml.jackson.databind.*;import com.hmdp.ai.domain.run.ExecutionContext;import com.hmdp.ai.port.*;import com.hmdp.ai.runtime.tool.*;import com.hmdp.ai.runtime.tool.skill.dto.*;import com.hmdp.dto.ai.ShopView;import org.springframework.stereotype.Component;import java.util.*;
@Component @AgentSkill(code="compare-shops") public class CompareShopsSkill extends ShopSkillSupport implements LocalSkill {public CompareShopsSkill(ShopDataPort s,ReviewDataPort r,ObjectMapper m){super(s,r,m);}@Override public JsonNode execute(ExecutionContext c,JsonNode in){if(!in.path("shopIds").isArray()||in.path("shopIds").size()<2)throw new IllegalArgumentException("at least two shopIds are required");List<ShopComparisonItemData>items=new ArrayList<>();for(JsonNode n:in.path("shopIds")){long id=n.asLong();ShopView s=shops.getShop(id);if(s!=null){int rc=shops.getReviewCount(id);double score=(s.getScore()==null?0:s.getScore())/10.0+Math.log10(Math.max(1,rc));items.add(new ShopComparisonItemData(s,rc,Math.round(score*100.0)/100.0));}}items.sort(Comparator.comparingDouble(ShopComparisonItemData::getNormalizedScore).reversed());return json(new ShopComparisonData(in.path("aspect").asText(null),items,items.isEmpty()?null:items.get(0).getShop().getId()));}}
